on (t.OLD_MODEL = s.OLD_MODEL and t.NEW_MODEL = s.NEW_MODEL)
when not matched then insert (MAPID, VENDORNAME, OLD_MODEL, NEW_MODEL, SOURCE_SHEET, ENABLEDFLAG, CREATEUSER, CREATETIME)
values (rawtohex(sys_guid()), s.VENDORNAME, s.OLD_MODEL, s.NEW_MODEL, s.SOURCE_SHEET, 'Y', 'SYSTEM', sysdate);

